def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))

    # Find the topmost horizontal run, which is the marker to recolor.
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            e = c + 1
            while e < w and row[e] == row[c]:
                e += 1
            if e - c >= 2 and row[c] != bg:
                runs.append((r, c, e, row[c]))
            c = e
    if not runs:
        return [row[:] for row in grid]
    r0 = min(r for r, _, _, _ in runs)
    marker = min((x for x in runs if x[0] == r0), key=lambda x: x[1])
    _, c0, c1, marker_color = marker

    # Choose the color of the long stripe-like object in the lower portion.
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if color == marker_color:
                continue
            rows = {}
            cols = {}
            for y, x in cells:
                rows[y] = rows.get(y, 0) + 1
                cols[x] = cols.get(x, 0) + 1
            longest = max(max(rows.values()), max(cols.values()))
            low = max(y for y, x in cells)
            candidates.append((longest, low, len(cells), color))

    if not candidates:
        return [row[:] for row in grid]
    # Favor a long run that belongs to an object extending well down the grid.
    _, _, _, target_color = max(candidates, key=lambda z: (z[0], z[1], z[2]))

    out = [row[:] for row in grid]
    for c in range(c0, c1):
        if out[r0][c] == marker_color:
            out[r0][c] = target_color
    return out
